module adder(
    input wire a,
    input wire b,
    input wire cin,
    output reg sum
);

    // Declare the carry-in and carry-out signals
    reg cin_i = cin;
    reg carry_out;

    // Add the two bits
    reg s0 = a ^ b;

    // Calculate the carry-out from the sum and carry-in
    always @(posedge s0, posedge cin_i) begin
        if (cin_i == 1 && s0 == 1) begin
            carry_out = 1;
        end else begin
            carry_out = 0;
        end
    end

    // Calculate the sum
    assign sum = s0 ^ carry_out;

endmodule
