module TopModule (
    input wire mode,
    input wire too_cold,
    input wire too_hot,
    input wire fan_on,
    output reg heater,
    output reg aircon,
    output reg fan
);

    // Constants
    localparam HEATER_ON = 1;
    localparam HEATER_OFF = 0;
    localparam AIRCON_ON = 1;
    localparam AIRCON_OFF = 0;
    localparam FAN_ON = 1;
    localparam FAN_OFF = 0;

    // Boolean variables for state management
    reg heater_state;
    reg aircon_state;
    reg fan_state;

    // State transitions
    always @(posedge mode or posedge too_cold or posedge too_hot or posedge fan_on) begin
        // Initialize state variables to off
        heater_state <= HEATER_OFF;
        aircon_state <= AIRCON_OFF;
        fan_state <= FAN_OFF;

        // Mode transitions
        if (mode == HEATER_ON) begin
            // Heater ON
            heater_state <= HEATER_ON;
            aircon_state <= AIRCON_OFF;
            fan_state <= FAN_ON;
        end
        else if (mode == AIRCON_ON) begin
            // Aircon ON
            heater_state <= HEATER_OFF;
            aircon_state <= AIRCON_ON;
            fan_state <= FAN_ON;
        end
    end

    // Condition transitions
    always @(posedge too_cold or posedge too_hot) begin
        if (too_cold) begin
            // Too Cold
            heater_state <= HEATER_ON;
            aircon_state <= AIRCON_OFF;
        end
        else if (too_hot) begin
            // Too Hot
            heater_state <= HEATER_OFF;
            aircon_state <= AIRCON_ON;
        end
    end

    // Fan ON transition
    always @(posedge fan_on) begin
        if (fan_on) begin
            // Fan ON
            heater_state <= HEATER_ON;
            aircon_state <= AIRCON_ON;
            fan_state <= FAN_ON;
        end
    end

    // Output assignment
    assign heater = heater_state;
    assign aircon = aircon_state;
    assign fan = fan_state;

